# Batch 2: Growth, Happiness, Healing, Leadership, Life, Love, Mindfulness

BATCH2_QUOTES = {
    "Growth": [
        {"id": "q_3", "text": "Progress, not perfection. Every effort is a seed planted in patience.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Calm,Hopeful", "situations": "Difficult Day,Study Time,Starting Over"},
        {"id": "q_44", "text": "There is no failure except in no longer trying.", "author": "Elbert Hubbard", "isOriginal": False, "source": "Essays", "moods": "Determined,Hopeful", "situations": "Difficult Day,Starting Over,Study Time"},
        {"id": "q_grow_1", "text": "Growth is not a straight arrow; it is a spiral that passes through the same seasons with wider eyes.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Starting Over,Difficult Day"},
        {"id": "q_grow_2", "text": "The seed splits in complete darkness before it ever greets the light. Do not despise the underground season.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_grow_3", "text": "Every skill you admire today was once an awkward, embarrassing first attempt. Begin clumsily.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Motivated", "situations": "Study Time,Starting Over"},
        {"id": "q_grow_4", "text": "Pruning feels like loss until springtime arrives and new blossoms burst from the cuts.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Hopeful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_grow_5", "text": "Maturity is learning to pause in the space between being provoked and choosing your response.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Before Work,Difficult Day"},
        {"id": "q_grow_6", "text": "The tree whose roots touch underground water does not fear the drought of summer.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Morning,Difficult Day"},
        {"id": "q_grow_7", "text": "Do not resist outgrowing old conversations and habits that no longer feed your spirit.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Starting Over,Before Sleep"},
        {"id": "q_grow_8", "text": "A mistake is only tuition paid to life. Make sure you take home the lesson you paid for.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Difficult Day,Study Time"},
        {"id": "q_grow_9", "text": "Patience with your own slow unfolding is the highest form of self-respect.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_grow_10", "text": "When you change your mind upon learning new truth, celebrate. It means you are alive and thinking.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Study Time,Before Work"},
        {"id": "q_grow_11", "text": "Quiet reflection at the end of the day transforms raw experience into lasting wisdom.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_grow_12", "text": "Do not pull on the petals to make the flower bloom faster. Provide sunlight and let time work.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_grow_13", "text": "Real transformation makes almost no noise. It happens in the private decisions you make when alone.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Starting Over,Before Sleep"},
        {"id": "q_grow_14", "text": "To forgive your past self is to untie the weight anchored to your ankles.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Starting Over,Difficult Day"},
        {"id": "q_grow_15", "text": "Look at how much you know today that baffled you three years ago. Give your future self the same credit.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Confident", "situations": "Study Time,Difficult Day"},
        {"id": "q_grow_16", "text": "Tend the garden of your mind. Pull out the thistles of resentment before their roots bite deep.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Healing", "situations": "Morning,Difficult Day"},
        {"id": "q_grow_17", "text": "Curiosity will carry you farther into life than intellect alone ever could.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Happy", "situations": "Study Time,Morning"},
        {"id": "q_grow_18", "text": "The shell must crack for the chick to emerge. Do not curse the breaking of the old container.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Determined", "situations": "Starting Over,Difficult Day"},
        {"id": "q_grow_19", "text": "Wisdom is not accumulating more facts, but shedding illusions until only what is real remains.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Study Time,Before Sleep"},
        {"id": "q_grow_20", "text": "Give yourself permission to become someone who handles storms with quiet composure.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Peace", "situations": "Before Work,Difficult Day"},
        {"id": "q_grow_21", "text": "An oak tree does not compete with the willow beside it; both enrich the meadow by being what they are.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Morning,Difficult Day"},
        {"id": "q_grow_22", "text": "Let go of the version of your life you rehearsed so you can inhabit the life actually before you.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Starting Over,Difficult Day"},
        {"id": "q_grow_23", "text": "Every habit you practice today is building the home your older self will live in.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Thoughtful", "situations": "Morning,Before Work"},
        {"id": "q_grow_24", "text": "The quietest days of steady practice often yield the deepest roots.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Study Time,Before Work"},
        {"id": "q_grow_25", "text": "You do not grow by avoiding hardship, but by meeting it with an upright spine and open eyes.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Difficult Day,Workout"},
        {"id": "q_grow_26", "text": "Patience is faith in the invisible work happening beneath the soil.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Calm", "situations": "Study Time,Starting Over"},
        {"id": "q_grow_27", "text": "Measure your day not by the harvest reaped, but by the seeds faithfully sown.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Thoughtful", "situations": "Before Sleep,Before Work"},
        {"id": "q_grow_28", "text": "A life well lived is a continuous act of gentle refinement.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Before Sleep"}
    ],

    "Happiness": [
        {"id": "q_happ_1", "text": "Happiness is not a prize at the end of a marathon; it is noticing the smell of woodsmoke in the evening air right now.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_happ_2", "text": "Joy lives in simple borders: fresh bedsheets, clean water, warm bread, and a quiet room.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Happy", "situations": "Morning,Before Sleep"},
        {"id": "q_happ_3", "text": "Do not postpone joy until all problems are solved. Life will always have problems; enjoy your tea anyway.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Wise", "situations": "Difficult Day,Morning"},
        {"id": "q_happ_4", "text": "Laughter with someone you trust is the shortest bridge between two souls.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Warm", "situations": "Difficult Day,Morning"},
        {"id": "q_happ_5", "text": "Lighten your grip on the day. Much of our misery comes from squeezing life too hard.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_happ_6", "text": "A walk through the woods with no destination is medicine that money cannot purchase.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_happ_7", "text": "Cheerfulness is a quiet rebellion against a world that profits from your anxiety.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Happy", "situations": "Morning,Before Work"},
        {"id": "q_happ_8", "text": "Delight in the accomplishments of others; it multiplies the joy available in the room.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Happy", "situations": "Before Work,Difficult Day"},
        {"id": "q_happ_9", "text": "The morning sun coming through the windowpane asks for nothing from you other than to be enjoyed.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Warm", "situations": "Morning,Difficult Day"},
        {"id": "q_happ_10", "text": "Do one useless, delightful thing today: watch a sparrow, skip a stone, read a poem aloud.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Playful", "situations": "Study Time,Before Sleep"},
        {"id": "q_happ_11", "text": "True contentment comes when you no longer need the world to applaud your every gesture.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Work,Before Sleep"},
        {"id": "q_happ_12", "text": "Keep your wants few and your gratitude wide, and you will live richer than any king.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Morning,Before Sleep"},
        {"id": "q_happ_13", "text": "A warm bowl of soup shared with a friend can banish the deepest chill from the heart.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Warm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_happ_14", "text": "Do not let the thief of comparison rob your garden of its rightful blossom.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Difficult Day,Morning"},
        {"id": "q_happ_15", "text": "Find pleasure in the craft itself, not just in the medal at the finish line.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Happy", "situations": "Before Work,Study Time"},
        {"id": "q_happ_16", "text": "Sing softly while you wash the dishes. Infuse ordinary chores with quiet goodwill.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_happ_17", "text": "The greatest freedom is being happy with the shoes you are wearing today.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Happy", "situations": "Morning,Difficult Day"},
        {"id": "q_happ_18", "text": "Let go of resentment. It is drinking bitter water and hoping the other person chokes.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Starting Over"},
        {"id": "q_happ_19", "text": "Notice how children look at puddles. Recover that holy instinct for curiosity.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Wonder", "situations": "Morning,Difficult Day"},
        {"id": "q_happ_20", "text": "Peace of mind is the quiet soil from which all lasting happiness springs.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Morning"},
        {"id": "q_happ_21", "text": "Smile at the stranger passing on the street. Kindness costs nothing and alters the weather.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Happy", "situations": "Morning,Before Work"},
        {"id": "q_happ_22", "text": "Enjoy your work while your hands are able. Labor done with love is pure joy.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Happy", "situations": "Before Work,Study Time"},
        {"id": "q_happ_23", "text": "A quiet conscience is the softest pillow known to humanity.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_happ_24", "text": "Celebrate ordinary days with the same gratitude you reserve for birthdays.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Warm", "situations": "Morning,Before Work"},
        {"id": "q_happ_25", "text": "Happiness is wanting what you have, not having what you want.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_happ_26", "text": "Sit on the steps in the morning sun and drink your coffee before the noise begins.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Happy", "situations": "Morning,Difficult Day"},
        {"id": "q_happ_27", "text": "Be easy on yourself today. You are a human being, not a productivity engine.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_happ_28", "text": "The greatest luxury is unhurried time with someone whose presence feels like home.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Happy", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_happ_29", "text": "Rejoice in the good that is present today, and trust tomorrow with tomorrow's needs.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_happ_30", "text": "Joy is an inside job that needs no external validation to shine.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Happy", "situations": "Morning,Need Confidence"}
    ],

    "Healing": [
        {"id": "q_heal_1", "text": "Healing is not a race to erase what happened; it is learning to carry your story with gentle hands.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Calm", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_2", "text": "Give your grief the dignity of time. Even the deepest fracture in the bone heals through quiet resting.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_heal_3", "text": "You do not have to explain your exhaustion to anyone today. Rest until your spirit catches up.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_heal_4", "text": "Treat the tender parts of your heart like a sparrow with a broken wing: shelter it from cold wind.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Healing", "situations": "Difficult Day,Morning"},
        {"id": "q_heal_5", "text": "The storm always passes. The sun never forgot how to warm the stones.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Calm", "situations": "Difficult Day,Morning"},
        {"id": "q_heal_6", "text": "Forgiveness is not excusing what hurt you; it is taking your hand off the hot stove.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Wise", "situations": "Starting Over,Difficult Day"},
        {"id": "q_heal_7", "text": "Let tears fall if they must. Salt water cleanses both the sea and the eyes.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_heal_8", "text": "Scars are proof that you survived the battle and your skin knitted back together.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_9", "text": "Step into the shower and let warm water run down your spine. Wash away the day's heavy weight.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Healing", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_heal_10", "text": "You are allowed to walk away from tables where respect is no longer served.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Determined", "situations": "Starting Over,Before Work"},
        {"id": "q_heal_11", "text": "A bruised reed is not broken; it bends with the wind until the season turns.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Calm", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_12", "text": "Do not judge your healing by the good days alone; count the days you chose not to give up.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Healing", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_heal_13", "text": "Breathe in clean air. Your lungs are willing to start fresh on every single inhalation.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Morning,Difficult Day"},
        {"id": "q_heal_14", "text": "Speak gently to yourself. The voice you hear most often is your own.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Healing", "situations": "Morning,Before Sleep"},
        {"id": "q_heal_15", "text": "Sit in silence with a warm cup of herbal tea. Let stillness knit your frayed edges.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_heal_16", "text": "The heart has its own seasons. Honor the winter so the spring can arrive in its own time.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_17", "text": "You do not need to be strong for everyone today. Lay down the armor for an hour.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_heal_18", "text": "Nature heals without shouting. Notice how moss spreads across old stone without friction.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_heal_19", "text": "Pain asks to be felt, but it does not ask to be made your permanent dwelling place.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_20", "text": "Every morning you wake is an invitation to begin with tender, unhurried mercy.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Peace", "situations": "Morning,Starting Over"},
        {"id": "q_heal_21", "text": "Release the grip on the story of how you were wronged. Make room for the story of how you thrived.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Healing", "situations": "Starting Over,Difficult Day"},
        {"id": "q_heal_22", "text": "There is a quiet dignity in surviving a long drought and remaining green at the core.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Peace", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_23", "text": "Be as patient with yourself as you would be with a child learning to walk on uneven stones.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Healing", "situations": "Starting Over,Difficult Day"},
        {"id": "q_heal_24", "text": "Sleep is the body's sanctuary. Lay down your burdens at the bedroom door.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_heal_25", "text": "The broken places in us are where light enters and compassion takes root.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_26", "text": "You are not broken beyond repair; you are in the workshop of restoration.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Confident", "situations": "Starting Over,Difficult Day"},
        {"id": "q_heal_27", "text": "Take your time. A deep wound takes deep quiet to knit together.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_heal_28", "text": "Surround yourself with quiet people who do not demand performance when you are bruised.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_heal_29", "text": "The sun rises tomorrow with no grudge against the darkness of tonight. Receive that same grace.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Hopeful", "situations": "Morning,Before Sleep"},
        {"id": "q_heal_30", "text": "Mending is sacred work. Honor the slow knitting of your strength.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Before Sleep,Difficult Day"}
    ],

    "Leadership": [
        {"id": "q_lead_1", "text": "True leadership is taking the blame when things go wrong and stepping back when praise is handed out.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Confident", "situations": "Before Work,Study Time"},
        {"id": "q_lead_2", "text": "Lead by the quiet example of your own craftsmanship, not by the volume of your voice.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Confident", "situations": "Before Work,Study Time"},
        {"id": "q_lead_3", "text": "A great leader does not create followers; they cultivate leaders who can stand on their own feet.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Wise", "situations": "Before Work,Starting Over"},
        {"id": "q_lead_4", "text": "Listen three times more than you speak. The room will tell you what it needs if you quiet your own agenda.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Before Work,Difficult Day"},
        {"id": "q_lead_5", "text": "Protect your people from unnecessary panic. Be the calm center when the seas turn rough.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Calm", "situations": "Before Work,Difficult Day"},
        {"id": "q_lead_6", "text": "Integrity in small matters is the only foundation that will support great authority.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_lead_7", "text": "Praise the quiet work done in the corners that keeps the entire structure standing.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Warm", "situations": "Before Work,Difficult Day"},
        {"id": "q_lead_8", "text": "A leader is the one who sweeps the snow from the steps before the team arrives.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Motivated", "situations": "Morning,Before Work"},
        {"id": "q_lead_9", "text": "Do not demand from others what you are unwilling to carry with your own back.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Fair", "situations": "Before Work,Workout"},
        {"id": "q_lead_10", "text": "Clarity of purpose gives courage to the entire team. State the destination plainly.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Confident", "situations": "Before Work,Study Time"},
        {"id": "q_lead_11", "text": "When the wind blows against you, lean forward with patience. The mast bends so the ship may ride.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Difficult Day,Before Work"},
        {"id": "q_lead_12", "text": "True authority is given freely by those who trust your judgment and benevolence.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Before Work,Study Time"},
        {"id": "q_lead_13", "text": "A good captain does not curse the storm; they adjust the sails and reassure the crew.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Calm", "situations": "Difficult Day,Before Work"},
        {"id": "q_lead_14", "text": "Leave the campsite cleaner than you found it. That is the fundamental rule of all stewardship.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Humble", "situations": "Morning,Before Work"},
        {"id": "q_lead_15", "text": "Never let ambition outrun your capacity for kindness.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Wise", "situations": "Before Work,Before Sleep"},
        {"id": "q_lead_16", "text": "Encourage the hesitant voice in the meeting. Often the best idea is the one spoken most quietly.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_lead_17", "text": "Take responsibility without hesitation; distribute credit without reservation.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Confident", "situations": "Before Work,Difficult Day"},
        {"id": "q_lead_18", "text": "A steady temperament in crisis is worth fifty brilliant speeches.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Difficult Day,Before Work"},
        {"id": "q_lead_19", "text": "Lead for the long haul. A sprint wins applause today, but endurance builds kingdoms.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Wise", "situations": "Before Work,Starting Over"},
        {"id": "q_lead_20", "text": "Keep your word, especially when keeping it costs you something tangible.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Honorable", "situations": "Before Work,Study Time"},
        {"id": "q_lead_21", "text": "Give your people the freedom to fail in the pursuit of something noble.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Hopeful", "situations": "Before Work,Starting Over"},
        {"id": "q_lead_22", "text": "Stand between your team and the storm; stand behind them when the sun breaks through.", "author": "Stillwords", "isOriginal": True, "moods": "Protective,Noble", "situations": "Difficult Day,Before Work"},
        {"id": "q_lead_23", "text": "Wisdom in leadership knows when to step forward and when to step out of the way.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_lead_24", "text": "A community thrives when elder thinkers plant trees under whose shade they will never sit.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Wise", "situations": "Morning,Before Work"},
        {"id": "q_lead_25", "text": "Do not confuse loudness for strength or cruelty for resolve.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Confident", "situations": "Before Work,Difficult Day"},
        {"id": "q_lead_26", "text": "The greatest leaders leave behind organizations that do not need them to survive.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Wise", "situations": "Before Work,Starting Over"},
        {"id": "q_lead_27", "text": "Listen to the frontline before you make decisions in the tower.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_lead_28", "text": "When you must correct, do it in private with dignity. When you praise, do it with genuine generosity.", "author": "Stillwords", "isOriginal": True, "moods": "Fair,Warm", "situations": "Before Work,Difficult Day"},
        {"id": "q_lead_29", "text": "Hold the standard high, but keep the door wide open for those who want to learn.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Generous", "situations": "Study Time,Before Work"},
        {"id": "q_lead_30", "text": "Leadership is serving the common good with clean hands and an unhurried heart.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Peace", "situations": "Morning,Before Work"}
    ],

    "Life": [
        {"id": "q_6", "text": "Before the morning asks anything of you, give the first five minutes to silence. Notice the cool glass against your fingers, the slow lifting of the fog.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Calm,Peace", "situations": "Morning,Before Work"},
        {"id": "q_life_1", "text": "Life is not a puzzle to be solved; it is an evening walk to be experienced with senses wide open.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Thoughtful", "situations": "Before Sleep,Morning"},
        {"id": "q_life_2", "text": "Notice the slant of winter light across the kitchen table. Beauty does not ask for permission to enter.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Calm", "situations": "Morning,Difficult Day"},
        {"id": "q_life_3", "text": "We are here for a brief visit. Leave the trail clearer than when you found it.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Thoughtful", "situations": "Morning,Before Sleep"},
        {"id": "q_life_4", "text": "Do not hurry through your years like a traveler anxious only for the terminal. Savor the train ride.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_life_5", "text": "The seasons change without apology. Let autumn teach you the grace of letting go.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Starting Over,Difficult Day"},
        {"id": "q_life_6", "text": "Live so that you have no secret that would shame you if whispered on the wind.", "author": "Stillwords", "isOriginal": True, "moods": "Honorable,Confident", "situations": "Before Work,Before Sleep"},
        {"id": "q_life_7", "text": "The greatest moments are rarely announced with trumpets. They are quiet afternoons when love was present.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_life_8", "text": "Death is the boundary that gives every single hour its astonishing value. Spend your minutes with reverence.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Thoughtful", "situations": "Morning,Before Sleep"},
        {"id": "q_life_9", "text": "Do not let the regrets of yesterday poison the water of today's fresh spring.", "author": "Stillwords", "isOriginal": True, "moods": "Relieved,Peace", "situations": "Starting Over,Morning"},
        {"id": "q_life_10", "text": "Walk softly upon the earth. You are part of its tapestry, not its owner.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_life_11", "text": "There is time enough for everything that truly matters. Trim away the rest.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_life_12", "text": "To sit with an old friend and watch the sun go down: that is the height of human civilization.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Warm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_life_13", "text": "Allow life to be mysterious. A mapped-out path has no room for miraculous detours.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Wonder", "situations": "Starting Over,Morning"},
        {"id": "q_life_14", "text": "Drink deeply from the cup of the present hour. It will never be refilled with the same wine.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Mindful", "situations": "Morning,Before Sleep"},
        {"id": "q_life_15", "text": "Let your home be a refuge of quiet speech and honest hospitality.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_life_16", "text": "Every morning brings twenty-four untouched hours. What a magnificent gift to be handed every dawn.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Motivated", "situations": "Morning,Starting Over"},
        {"id": "q_life_17", "text": "Do not fear growing older. The grain in weathered wood is always richer than fresh timber.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Calm", "situations": "Before Sleep,Morning"},
        {"id": "q_life_18", "text": "Pay attention to the transitions: between waking and sleeping, between autumn and winter. That is where poetry lives.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Thoughtful", "situations": "Morning,Before Sleep"},
        {"id": "q_life_19", "text": "A life of simplicity leaves room for the heart to breathe.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Morning,Before Sleep"},
        {"id": "q_life_20", "text": "Listen to the rain tapping on the tin roof. The world is washing itself clean without your help.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_life_21", "text": "You do not need to leave a monument of stone. Leave a legacy of kindness in living hearts.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Wise", "situations": "Before Sleep,Morning"},
        {"id": "q_life_22", "text": "Make peace with what you cannot change, and bring all your energy to what you can.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Peace", "situations": "Difficult Day,Before Work"},
        {"id": "q_life_23", "text": "The greatest treasure is a quiet mind that desires little and appreciates everything.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Morning,Before Sleep"},
        {"id": "q_life_24", "text": "Look at the stars tonight. Feel your smallness, and feel the wonder of being part of it all.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_life_25", "text": "Life asks only that you show up with an honest heart and do your best with what is in front of you.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Determined", "situations": "Morning,Before Work"},
        {"id": "q_life_26", "text": "The best days are those where you were so absorbed in the moment that you forgot to check the time.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Focused", "situations": "Study Time,Before Sleep"},
        {"id": "q_life_27", "text": "Kindness is the language that the deaf can hear and the blind can see. Speak it fluently.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Generous", "situations": "Morning,Before Work"},
        {"id": "q_life_28", "text": "Do not let the world rush you past the beauty that took centuries to arrive.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wonder", "situations": "Morning,Difficult Day"},
        {"id": "q_life_29", "text": "Everything in this world is passing. Hold what you love with open palms.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Before Sleep,Difficult Day"}
    ],

    "Love": [
        {"id": "q_love_1", "text": "Love is not gazing into each other's eyes; it is standing side by side looking forward into the same horizon.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Hopeful", "situations": "Morning,Before Sleep"},
        {"id": "q_love_2", "text": "To love someone is to make room for their imperfections without keeping a balance sheet.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_love_3", "text": "True love is shown in small kindnesses: hot coffee poured, blankets pulled up, listening when tired.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Happy", "situations": "Morning,Before Sleep"},
        {"id": "q_love_4", "text": "Love does not seek to conquer or mold; it waters the roots so the other person may bloom in their own colors.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Wise", "situations": "Morning,Starting Over"},
        {"id": "q_love_5", "text": "When you love without condition, fear loses its grip on the household.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Confident", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_love_6", "text": "A warm hand held in the quiet dark can anchor a spirit that feels adrift.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Healing", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_love_7", "text": "Patience is love's everyday clothing. Wear it when the days are long and nerves are frayed.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Gentle", "situations": "Difficult Day,Before Work"},
        {"id": "q_love_8", "text": "To be truly known by another human being and met with unwavering acceptance is life's greatest shelter.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Warm", "situations": "Before Sleep,Morning"},
        {"id": "q_love_9", "text": "Love speaks softly. It never needs to scream to make itself felt.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_love_10", "text": "Forgive quickly. The hours of life are too precious to burn on the altar of resentment.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Starting Over"},
        {"id": "q_love_11", "text": "Shared memories of ordinary afternoons become the golden tapestry of an entire lifetime.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Happy", "situations": "Before Sleep,Morning"},
        {"id": "q_love_12", "text": "Love is staying when running away would be easier.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Noble", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_love_13", "text": "Let love be the filter through which all your daily judgments pass.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Morning,Before Work"},
        {"id": "q_love_14", "text": "The heart grows larger every time it gives away a measure of its affection.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Happy", "situations": "Morning,Before Work"},
        {"id": "q_love_15", "text": "In a world that rushes to criticize, be the one who offers shelter and understanding.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Gentle", "situations": "Before Work,Difficult Day"},
        {"id": "q_love_16", "text": "Love is not an emotion that visits and flees; it is a vow practiced with every sunrise.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Faithful", "situations": "Morning,Before Sleep"},
        {"id": "q_love_17", "text": "Notice what brings joy to the person beside you and quietly help make it happen.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Warm", "situations": "Morning,Before Work"},
        {"id": "q_love_18", "text": "A home filled with love has thicker walls than a fortress made of granite.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Confident", "situations": "Before Sleep,Morning"},
        {"id": "q_love_19", "text": "Speak words of affirmation while ears can still hear them.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Thoughtful", "situations": "Morning,Before Sleep"},
        {"id": "q_love_20", "text": "The greatest bravery is opening your heart again after it was once bruised.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Healing", "situations": "Starting Over,Difficult Day"},
        {"id": "q_love_21", "text": "True love listens to what remains unsaid in the silence between words.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_love_22", "text": "Delight in the presence of those you cherish. Their presence is today's miracle.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Warm", "situations": "Morning,Before Sleep"},
        {"id": "q_love_23", "text": "Love does not boast of what it sacrificed; it rejoices in what it gave.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Humble", "situations": "Before Sleep,Before Work"},
        {"id": "q_love_24", "text": "A gentle answer turns away wrath and builds a bridge where a wall threatened to rise.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Difficult Day,Before Work"},
        {"id": "q_love_25", "text": "Love is the only treasure that multiplies when divided among others.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Happy", "situations": "Morning,Before Work"},
        {"id": "q_love_26", "text": "Stand beside those you love when winter tests their boughs.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Warm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_love_27", "text": "When you walk in love, fear finds no hospitable room to unpack its bags.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_love_28", "text": "Honor the vulnerability of the heart that trusts you with its deepest secrets.", "author": "Stillwords", "isOriginal": True, "moods": "Faithful,Noble", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_love_29", "text": "To love deeply is to accept that you will be changed by the journey.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Hopeful", "situations": "Starting Over,Morning"},
        {"id": "q_love_30", "text": "Love is the light that guides humanity through the longest and coldest nights.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Peace", "situations": "Before Sleep,Difficult Day"}
    ],

    "Mindfulness": [
        {"id": "q_9", "text": "The soul becomes dyed with the color of its thoughts.", "author": "Marcus Aurelius", "isOriginal": False, "source": "Meditations", "moods": "Thoughtful,Calm", "situations": "Morning,Before Sleep"},
        {"id": "q_18", "text": "You do not need to push the river. Water finds its way around stone simply by never forgetting where the ocean is.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Calm,Peace", "situations": "Morning,Before Sleep,Difficult Day"},
        {"id": "q_21", "text": "Take a deep breath and feel the soles of your feet on the floor. In this single breath, nothing is required of you other than to be here.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Calm,Peace", "situations": "Morning,Before Sleep,Difficult Day"},
        {"id": "q_46", "text": "The morning does not arrive all at once; it washes into the corners of the room in gray, then pearl, then gold. You too are allowed to wake gently.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Calm,Hopeful", "situations": "Morning,Starting Over"},
        {"id": "q_mind_1", "text": "Be present where your feet are planted. Half of our sorrow lives in a past we cannot alter, and half in a future that does not exist.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Peace", "situations": "Morning,Before Work"},
        {"id": "q_mind_2", "text": "Notice the air entering your nostrils: cool on the way in, warm on the way out. That breath is life sustaining you.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Mindful", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_mind_3", "text": "Step out of the rushing river of thoughts and sit upon the grassy bank. Watch them drift past like leaves.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Difficult Day,Study Time"},
        {"id": "q_mind_4", "text": "When washing dishes, only wash dishes. Let your mind be wholly present with warm water and porcelain.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Calm", "situations": "Morning,Before Sleep"},
        {"id": "q_mind_5", "text": "Quiet the chatter in your head so you can hear the birds singing in the morning yard.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wonder", "situations": "Morning,Difficult Day"},
        {"id": "q_mind_6", "text": "This present moment is the only place where life actually occurs. Do not miss it while rehearsing tomorrow.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Mindful", "situations": "Before Work,Study Time"},
        {"id": "q_mind_7", "text": "Eat your bread with undivided attention. Taste the wheat, the salt, the yeast. Give thanks.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Peace", "situations": "Morning,Before Work"},
        {"id": "q_mind_8", "text": "Feel the coolness of the morning breeze against your cheek. The earth is alive and breathing with you.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Calm", "situations": "Morning,Difficult Day"},
        {"id": "q_mind_9", "text": "You are not your anxious thoughts; you are the calm sky in which those thoughts form and dissolve.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_mind_10", "text": "Pause between one task and the next. Take three conscious breaths to reset the compass of your soul.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_mind_11", "text": "Listen to the person speaking to you as if they were the only human being in the universe right now.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Warm", "situations": "Before Work,Difficult Day"},
        {"id": "q_mind_12", "text": "Walk slowly enough that your soul does not feel abandoned by your hasty stride.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Difficult Day,Morning"},
        {"id": "q_mind_13", "text": "When you drink tea, drink tea. When you sit, sit. Do not divide your presence into tiny fragments.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Calm", "situations": "Morning,Before Sleep"},
        {"id": "q_mind_14", "text": "Let silence do the heavy lifting of clearing the clutter from your mind.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_mind_15", "text": "Notice the space between two breaths: that quiet stillness is the doorway to inner peace.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_mind_16", "text": "Do not rush through the threshold. Feel your hand upon the doorknob and arrive fully.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Focused", "situations": "Before Work,Morning"},
        {"id": "q_mind_17", "text": "A mindful person moves through the world like sunlight: illuminating everything without clinging to anything.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_mind_18", "text": "Tension is who you think you should be. Relaxation is who you actually are.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_mind_19", "text": "Observe your irritation as if it were a strange insect in a jar. Examine it without becoming it.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Before Work"},
        {"id": "q_mind_20", "text": "The past is memory; the future is imagination. The present alone is real.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Wise", "situations": "Study Time,Before Sleep"},
        {"id": "q_mind_21", "text": "Sit beneath an old tree and match your breathing to the slow sway of its branches.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Morning"},
        {"id": "q_mind_22", "text": "Bring awareness into the soles of your feet as you walk. Every step kisses the earth.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Peace", "situations": "Morning,Workout"},
        {"id": "q_mind_23", "text": "There is no storm inside you that quiet awareness cannot eventually calm.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Calm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_mind_24", "text": "Notice the taste of water before you swallow. Gratitude begins in simple awareness.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_mind_25", "text": "Return to the breath whenever the world spins too fast. It is your portable sanctuary.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Work"},
        {"id": "q_mind_26", "text": "Mindfulness is the art of befriending the present moment just as it is.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Warm", "situations": "Morning,Before Sleep"}
    ]
}
